  CAST(concat('capture ', "oq:format:s:::0:", ' of ', toString(length("oq:windows:u64h:::0:")), ' window(s) ', "oq:decision:s:::0:", ' -> ', "oq:phase:s:::0:", if(length("oq:reason:sh:::0:") > 0, concat(' (', arrayStringConcat("oq:reason:sh:::0:", ' | '), ')'), '')), 'String') AS "oq:headline:s:::0:",
  CAST('', 'String') AS "oq:text:s:::0:",
  CAST("oq:confined:b:::0:", 'Bool') AS "oq:confined:b:::0:",
  CAST(true, 'Bool') AS "oq:tainted:b:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-in:u64:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-out:u64:::0:",
  CAST(0, 'UInt64') AS "oq:elapsed-ms:u64:::0:"
FROM boxer.dm_trail_llm_agent_captures
UNION ALL
SELECT
  "id:id:u64:47::0:", "ts:ts:z64:47::0:", "id:naturalKey:y:4::0:", "oq:run:s:::0:", "oq:app:s:::0:", "oq:instance:u64:::0:", "oq:conversation:s:::0:", "oq:turn:s:::0:", "oq:round:u32:::0:", "oq:task:s:::0:", "oq:task-epoch:u64:::0:", "oq:task-call:s:::0:",
  CAST('agentDisclosure', 'String') AS "oq:kind:s:::0:",
  CAST("oq:digest:s:::0:", 'String') AS "oq:ref:s:::0:",
  CAST(0, 'UInt32') AS "oq:seq:u32:::0:",
  CAST("oq:cause-model-call:s:::0:", 'String') AS "oq:parent-ref:s:::0:",
  CAST("oq:decision:s:::0:", 'String') AS "oq:status:s:::0:",
  CAST("oq:source:s:::0:", 'String') AS "oq:subject:s:::0:",
  CAST(concat('disclosure of ', "oq:source:s:::0:", ' image at level ', "oq:level:s:::0:", ' ', "oq:decision:s:::0:", if("oq:decided-by:s:::0:" != '', concat(' by ', "oq:decided-by:s:::0:"), ''), if(length("oq:endpoint:sh:::0:") > 0, concat(' to ', arrayStringConcat("oq:endpoint:sh:::0:", ', ')), '')), 'String') AS "oq:headline:s:::0:",
  CAST(arrayStringConcat("oq:reason:sh:::0:", ' | '), 'String') AS "oq:text:s:::0:",
  CAST("oq:local-only:b:::0:", 'Bool') AS "oq:confined:b:::0:",
  CAST(false, 'Bool') AS "oq:tainted:b:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-in:u64:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-out:u64:::0:",
  CAST(0, 'UInt64') AS "oq:elapsed-ms:u64:::0:"
FROM boxer.dm_trail_llm_agent_disclosures
UNION ALL
SELECT
  "id:id:u64:47::0:", "ts:ts:z64:47::0:", "id:naturalKey:y:4::0:", "oq:run:s:::0:", "oq:app:s:::0:", "oq:instance:u64:::0:", "oq:conversation:s:::0:", "oq:turn:s:::0:", "oq:round:u32:::0:", "oq:task:s:::0:", "oq:task-epoch:u64:::0:", "oq:task-call:s:::0:",
  CAST('httpFetch', 'String') AS "oq:kind:s:::0:",
  CAST("oq:url:s:::0:", 'String') AS "oq:ref:s:::0:",
  CAST(0, 'UInt32') AS "oq:seq:u32:::0:",
  CAST('', 'String') AS "oq:parent-ref:s:::0:",
  CAST(if("oq:refused:b:::0:", 'refused', toString("oq:status:u32:::0:")), 'String') AS "oq:status:s:::0:",
  CAST("oq:destination:s:::0:", 'String') AS "oq:subject:s:::0:",
  CAST(concat("oq:method:s:::0:", ' ', "oq:destination:s:::0:", ' ', "oq:url:s:::0:", ' -> ', if("oq:refused:b:::0:", 'refused', toString("oq:status:u32:::0:")), ' (', toString("oq:bytes:u64:::0:"), ' bytes, ', toString("oq:elapsed-ms:u64:::0:"), ' ms)'), 'String') AS "oq:headline:s:::0:",
  CAST(arrayStringConcat("oq:error:sh:::0:", ' | '), 'String') AS "oq:text:s:::0:",
  CAST("oq:sensitivity:s:::0:" = 'confined', 'Bool') AS "oq:confined:b:::0:",
  CAST(false, 'Bool') AS "oq:tainted:b:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-in:u64:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-out:u64:::0:",
  CAST("oq:elapsed-ms:u64:::0:", 'UInt64') AS "oq:elapsed-ms:u64:::0:"
FROM boxer.dm_trail_http_fetches
UNION ALL
SELECT
  "id:id:u64:47::0:", "ts:ts:z64:47::0:", "id:naturalKey:y:4::0:", "oq:run:s:::0:", "oq:app:s:::0:", "oq:instance:u64:::0:", "oq:conversation:s:::0:", "oq:turn:s:::0:", "oq:round:u32:::0:", "oq:task:s:::0:", "oq:task-epoch:u64:::0:", "oq:task-call:s:::0:",
  CAST('adhocDataset', 'String') AS "oq:kind:s:::0:",
  CAST("oq:document-digest:s:::0:", 'String') AS "oq:ref:s:::0:",
  CAST(0, 'UInt32') AS "oq:seq:u32:::0:",
  CAST("oq:cause-model-call:s:::0:", 'String') AS "oq:parent-ref:s:::0:",
  CAST("oq:outcome:s:::0:", 'String') AS "oq:status:s:::0:",
  CAST("oq:bundle:s:::0:", 'String') AS "oq:subject:s:::0:",
  CAST(concat('bundle ', "oq:bundle:s:::0:", ' ', "oq:operation:s:::0:", ' r', toString("oq:revision:u64:::0:"), ' -> ', "oq:outcome:s:::0:", if(length("oq:local-names:sh:::0:") > 0, concat(' [', arrayStringConcat("oq:local-names:sh:::0:", ', '), ']'), ''), if("oq:attested:b:::0:", ' (attested)', ''), if(length("oq:reason:sh:::0:") > 0, concat(' (', arrayStringConcat("oq:reason:sh:::0:", ' | '), ')'), '')), 'String') AS "oq:headline:s:::0:",
  CAST(arrayStringConcat("oq:reason:sh:::0:", ' | '), 'String') AS "oq:text:s:::0:",
  CAST(false, 'Bool') AS "oq:confined:b:::0:",
  CAST(false, 'Bool') AS "oq:tainted:b:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-in:u64:::0:",
  CAST(0, 'UInt64') AS "oq:tokens-out:u64:::0:",
  CAST(0, 'UInt64') AS "oq:elapsed-ms:u64:::0:"
FROM boxer.dm_trail_adhoc_bundles
COMMENT 'keelson trail views v5 over leeway SQL read surface v2';

CREATE OR REPLACE VIEW boxer.agg_trail_llm_agent_action_outcomes AS
SELECT
  CAST(if("oq:key:s:::0:" = '', concat('row:', toString("id:id:u64:47::0:")), "oq:key:s:::0:"), 'String') AS "oq:action-key:s:::0:",
  CAST(any("oq:run:s:::0:"), 'String') AS "oq:run:s:::0:",
  CAST(any("oq:app:s:::0:"), 'String') AS "oq:app:s:::0:",
  CAST(any("oq:instance:u64:::0:"), 'UInt64') AS "oq:instance:u64:::0:",
  CAST(anyIf("oq:conversation:s:::0:", "oq:conversation:s:::0:" != ''), 'String') AS "oq:conversation:s:::0:",
  CAST(anyIf("oq:turn:s:::0:", "oq:turn:s:::0:" != ''), 'String') AS "oq:turn:s:::0:",
  CAST(anyIf("oq:task:s:::0:", "oq:task:s:::0:" != ''), 'String') AS "oq:task:s:::0:",
  CAST(max("oq:task-epoch:u64:::0:"), 'UInt64') AS "oq:task-epoch:u64:::0:",
  CAST(anyIf("oq:task-call:s:::0:", "oq:task-call:s:::0:" != ''), 'String') AS "oq:task-call:s:::0:",
  CAST(anyIf("oq:cause-model-call:s:::0:", "oq:cause-model-call:s:::0:" != ''), 'String') AS "oq:cause-model-call:s:::0:",
  CAST(any("oq:target-app:s:::0:"), 'String') AS "oq:target-app:s:::0:",
  CAST(any("oq:target-instance:u64:::0:"), 'UInt64') AS "oq:target-instance:u64:::0:",
  CAST(any("oq:operation:s:::0:"), 'String') AS "oq:operation:s:::0:",
  CAST(any("oq:effect:s:::0:"), 'String') AS "oq:effect:s:::0:",
  toDateTime64(min("ts:ts:z64:47::0:"), 9, 'UTC') AS "oq:first-ts:z64:::0:",
  toDateTime64(max("ts:ts:z64:47::0:"), 9, 'UTC') AS "oq:last-ts:z64:::0:",
  CAST(arrayMap(e -> e.2, arraySort(groupArray(("ts:ts:z64:47::0:", "oq:phase:s:::0:")))), 'Array(String)') AS "oq:phases:sh:::0:",
  CAST(argMax("oq:phase:s:::0:", "ts:ts:z64:47::0:"), 'String') AS "oq:outcome:s:::0:",
  CAST(argMax("oq:phase:s:::0:", "ts:ts:z64:47::0:") IN ('applied', 'rendered', 'completed'), 'Bool') AS "oq:done:b:::0:",
  CAST(argMax("oq:phase:s:::0:", "ts:ts:z64:47::0:") IN ('proposed', 'input_required'), 'Bool') AS "oq:waiting:b:::0:",
  CAST(argMax("oq:phase:s:::0:", "ts:ts:z64:47::0:") IN ('denied', 'refused', 'rejected', 'stale', 'conflict', 'expired', 'failed', 'cancelled'), 'Bool') AS "oq:not-done:b:::0:",
  CAST(argMaxIf("oq:reason:sh:::0:", "ts:ts:z64:47::0:", length("oq:reason:sh:::0:") > 0), 'Array(String)') AS "oq:reason:sh:::0:",
  CAST(argMinIf("oq:call-title:sh:::0:", "ts:ts:z64:47::0:", length("oq:call-title:sh:::0:") > 0), 'Array(String)') AS "oq:call-title:sh:::0:",
  CAST(argMinIf("oq:call-reason:sh:::0:", "ts:ts:z64:47::0:", length("oq:call-reason:sh:::0:") > 0), 'Array(String)') AS "oq:call-reason:sh:::0:",
  CAST(min("oq:budget-left:u32:::0:"), 'UInt32') AS "oq:budget-left:u32:::0:",
  CAST(max("oq:test:b:::0:"), 'Bool') AS "oq:test:b:::0:",
  CAST(max("oq:tainted:b:::0:"), 'Bool') AS "oq:tainted:b:::0:",
  CAST(max("oq:confined:b:::0:"), 'Bool') AS "oq:confined:b:::0:",
  CAST(groupArray("id:id:u64:47::0:"), 'Array(UInt64)') AS "oq:facts-ids:u64h:::0:"
FROM boxer.dm_trail_llm_agent_actions
GROUP BY if("oq:key:s:::0:" = '', concat('row:', toString("id:id:u64:47::0:")), "oq:key:s:::0:")
COMMENT 'keelson trail views v5 over leeway SQL read surface v2';

CREATE OR REPLACE VIEW boxer.agg_trail_llm_conversations AS
SELECT
  CAST(t.conversation, 'String') AS "oq:conversation:s:::0:",
  toDateTime64(t.first_ts, 9, 'UTC') AS "oq:first-ts:z64:::0:",
  toDateTime64(t.last_ts, 9, 'UTC') AS "oq:last-ts:z64:::0:",
  CAST(dateDiff('second', t.first_ts, t.last_ts), 'Int64') AS "oq:span-s:i64:::0:",
  CAST(t.apps, 'Array(String)') AS "oq:apps:sh:::0:",
  CAST(t.turns, 'UInt64') AS "oq:turns:u64:::0:",
  CAST(t.model_calls, 'UInt64') AS "oq:model-call-count:u64:::0:",
  CAST(t.calls_not_done, 'UInt64') AS "oq:model-calls-not-done:u64:::0:",
  CAST(t.tokens_in, 'UInt64') AS "oq:tokens-in:u64:::0:",
  CAST(t.tokens_out, 'UInt64') AS "oq:tokens-out:u64:::0:",
  CAST(t.messages, 'UInt64') AS "oq:message-count:u64:::0:",
  CAST(t.messages_kept, 'UInt64') AS "oq:messages-kept:u64:::0:",
  CAST(a.actions, 'UInt64') AS "oq:actions:u64:::0:",
  CAST(a.actions_done, 'UInt64') AS "oq:actions-done:u64:::0:",
  CAST(a.actions_waiting, 'UInt64') AS "oq:actions-waiting:u64:::0:",
  CAST(a.actions_not_done, 'UInt64') AS "oq:actions-not-done:u64:::0:",
  CAST(a.operations, 'Array(String)') AS "oq:operations:sh:::0:",
  CAST(t.tasks, 'Array(String)') AS "oq:tasks:sh:::0:",
  CAST(t.any_confined, 'Bool') AS "oq:any-confined:b:::0:",
  CAST(t.any_tainted, 'Bool') AS "oq:any-tainted:b:::0:",
  CAST(t.first_question, 'String') AS "oq:first-question:s:::0:",
  CAST(t.last_answer, 'String') AS "oq:last-answer:s:::0:",
  CAST(t.facts_ids, 'Array(UInt64)') AS "oq:facts-ids:u64h:::0:"
FROM (
  SELECT
    "oq:conversation:s:::0:" AS conversation,
    min("ts:ts:z64:47::0:") AS first_ts,
    max("ts:ts:z64:47::0:") AS last_ts,
    groupUniqArray("oq:app:s:::0:") AS apps,
    uniqExactIf("oq:turn:s:::0:", "oq:turn:s:::0:" != '') AS turns,
    countIf("oq:kind:s:::0:" = 'llmCall') AS model_calls,
    countIf("oq:kind:s:::0:" = 'llmCall' AND "oq:status:s:::0:" IN ('refused', 'incomplete')) AS calls_not_done,
    sum("oq:tokens-in:u64:::0:") AS tokens_in,
    sum("oq:tokens-out:u64:::0:") AS tokens_out,
    countIf("oq:kind:s:::0:" = 'llmMessage') AS messages,
    countIf("oq:kind:s:::0:" = 'llmMessage' AND "oq:text:s:::0:" != '') AS messages_kept,
    groupUniqArrayIf("oq:task:s:::0:", "oq:task:s:::0:" != '') AS tasks,
    max("oq:confined:b:::0:") AS any_confined,
    max("oq:tainted:b:::0:") AS any_tainted,
    argMinIf("oq:text:s:::0:", ("ts:ts:z64:47::0:", "oq:seq:u32:::0:"), "oq:kind:s:::0:" = 'llmMessage' AND "oq:status:s:::0:" = 'user' AND "oq:text:s:::0:" != '') AS first_question,
    argMaxIf("oq:text:s:::0:", ("ts:ts:z64:47::0:", "oq:seq:u32:::0:"), "oq:kind:s:::0:" = 'llmMessage' AND "oq:status:s:::0:" = 'assistant' AND "oq:text:s:::0:" != '') AS last_answer,
    groupArray("id:id:u64:47::0:") AS facts_ids
  FROM boxer.dm_trail_timeline
  WHERE "oq:conversation:s:::0:" != ''
  GROUP BY "oq:conversation:s:::0:"
) AS t
LEFT JOIN (
  SELECT
    "oq:conversation:s:::0:" AS conversation,
    count() AS actions,
    countIf("oq:done:b:::0:") AS actions_done,
    countIf("oq:waiting:b:::0:") AS actions_waiting,
    countIf("oq:not-done:b:::0:") AS actions_not_done,
    groupUniqArray(concat("oq:target-app:s:::0:", '.', "oq:operation:s:::0:")) AS operations
  FROM boxer.agg_trail_llm_agent_action_outcomes
  WHERE "oq:conversation:s:::0:" != ''
  GROUP BY "oq:conversation:s:::0:"
) AS a ON a.conversation = t.conversation
COMMENT 'keelson trail views v5 over leeway SQL read surface v2';

CREATE OR REPLACE VIEW boxer.agg_trail_llm_tasks AS
SELECT
  CAST(t.task, 'String') AS "oq:task:s:::0:",
  toDateTime64(t.first_ts, 9, 'UTC') AS "oq:first-ts:z64:::0:",
  toDateTime64(t.last_ts, 9, 'UTC') AS "oq:last-ts:z64:::0:",
  CAST(dateDiff('second', t.first_ts, t.last_ts), 'Int64') AS "oq:span-s:i64:::0:",
  CAST(t.conversations, 'Array(String)') AS "oq:conversations:sh:::0:",
  CAST(t.plan, 'String') AS "oq:plan:s:::0:",
  CAST(t.grant_events, 'Array(String)') AS "oq:grant-events:sh:::0:",
  CAST(t.last_grant_event, 'String') AS "oq:last-grant-event:s:::0:",
  CAST(has(t.grant_events, 'ended'), 'Bool') AS "oq:ended:b:::0:",
  CAST(a.actions, 'UInt64') AS "oq:actions:u64:::0:",
  CAST(a.actions_done, 'UInt64') AS "oq:actions-done:u64:::0:",
  CAST(a.actions_waiting, 'UInt64') AS "oq:actions-waiting:u64:::0:",
  CAST(a.actions_not_done, 'UInt64') AS "oq:actions-not-done:u64:::0:",
  CAST(a.operations, 'Array(String)') AS "oq:operations:sh:::0:",
  CAST(a.not_done_reasons, 'Array(String)') AS "oq:not-done-reasons:sh:::0:",
  CAST(t.captures, 'UInt64') AS "oq:captures:u64:::0:",
  CAST(t.delegated_model_calls, 'UInt64') AS "oq:delegated-model-calls:u64:::0:",
  CAST(t.delegated_tokens_in, 'UInt64') AS "oq:delegated-tokens-in:u64:::0:",
  CAST(t.delegated_tokens_out, 'UInt64') AS "oq:delegated-tokens-out:u64:::0:",
  CAST(t.any_confined, 'Bool') AS "oq:any-confined:b:::0:",
  CAST(t.any_tainted, 'Bool') AS "oq:any-tainted:b:::0:",
  CAST(t.facts_ids, 'Array(UInt64)') AS "oq:facts-ids:u64h:::0:"
FROM (
  SELECT
    "oq:task:s:::0:" AS task,
    min("ts:ts:z64:47::0:") AS first_ts,
    max("ts:ts:z64:47::0:") AS last_ts,
    groupUniqArrayIf("oq:conversation:s:::0:", "oq:conversation:s:::0:" != '') AS conversations,
    argMinIf("oq:text:s:::0:", "ts:ts:z64:47::0:", "oq:kind:s:::0:" = 'agentGrant' AND "oq:text:s:::0:" != '') AS plan,
    arrayMap(e -> e.2, arraySort(groupArrayIf(("ts:ts:z64:47::0:", "oq:status:s:::0:"), "oq:kind:s:::0:" = 'agentGrant'))) AS grant_events,
    argMaxIf("oq:status:s:::0:", "ts:ts:z64:47::0:", "oq:kind:s:::0:" = 'agentGrant') AS last_grant_event,
    countIf("oq:kind:s:::0:" = 'agentCapture') AS captures,
    countIf("oq:kind:s:::0:" = 'llmCall') AS delegated_model_calls,
    sum("oq:tokens-in:u64:::0:") AS delegated_tokens_in,
    sum("oq:tokens-out:u64:::0:") AS delegated_tokens_out,
    max("oq:confined:b:::0:") AS any_confined,
    max("oq:tainted:b:::0:") AS any_tainted,
    groupArray("id:id:u64:47::0:") AS facts_ids
  FROM boxer.dm_trail_timeline
  WHERE "oq:task:s:::0:" != ''
  GROUP BY "oq:task:s:::0:"
) AS t
LEFT JOIN (
  SELECT
    "oq:task:s:::0:" AS task,
    count() AS actions,
    countIf("oq:done:b:::0:") AS actions_done,
    countIf("oq:waiting:b:::0:") AS actions_waiting,
    countIf("oq:not-done:b:::0:") AS actions_not_done,
    groupUniqArray(concat("oq:target-app:s:::0:", '.', "oq:operation:s:::0:")) AS operations,
    groupUniqArrayIf(concat("oq:operation:s:::0:", ': ', "oq:outcome:s:::0:", if(length("oq:reason:sh:::0:") > 0, concat(' (', arrayStringConcat("oq:reason:sh:::0:", ' | '), ')'), '')), "oq:not-done:b:::0:") AS not_done_reasons
  FROM boxer.agg_trail_llm_agent_action_outcomes
  WHERE "oq:task:s:::0:" != ''
  GROUP BY "oq:task:s:::0:"
) AS a ON a.task = t.task
COMMENT 'keelson trail views v5 over leeway SQL read surface v2';
